/* Forkwood service worker (1.0 PWA). Generated by tools/pwa/build-sw.mjs; edit tools/pwa/sw.template.js.
   Scope is the folder sw.js sits in, so it works under the GitHub Pages subpath.
   - install: precache the app shell (index, css, core JS, fonts, first-world art)
   - index.html / navigations: network first, cached copy offline
   - same-origin assets: cache first (versioned cache, old versions dropped on activate)
   - other origins (PeerJS, CDNs, the poet worker): not touched */
const VERSION = '__VERSION__';
const SHELL = __SHELL__;
const CACHE = VERSION, RUNTIME = VERSION + '-rt';

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then(async (c) => {
    // one file at a time so a single 404 can never block install
    await Promise.all(SHELL.map((u) => c.add(new Request(u, { cache: 'reload' })).catch(() => {})));
  }).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k.startsWith('fw-') && k !== CACHE && k !== RUNTIME).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

const isHTML = (req, url) => req.mode === 'navigate' || url.pathname.endsWith('/') || url.pathname.endsWith('.html');

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // PeerJS, CDNs, workers: straight to the network
  if (req.headers.has('range')) return;            // audio range requests: let the browser handle them
  if (isHTML(req, url)) {
    e.respondWith(fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(url.pathname.endsWith('.html') ? req : './', copy)); }
      return res;
    }).catch(() => caches.match(req, { ignoreSearch: true }).then((r) => r || caches.match('./'))));
    return;
  }
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(RUNTIME).then((c) => c.put(req, copy)); }
    return res;
  })));
});
